configuration.tbelDecoder:
// 1. Decodifica del payload in ingresso
var raw = decodeToJson(payload);

// Se decodeToJson restituisce null o non è un oggetto, interrompi per evitare crash
if (!raw) {
    return null;
}

// 2. Estrazione sicura del corpo dati (gestisce sia payload annidato che diretto)
var data = raw.payload ? raw.payload : raw;

// 3. Estrazione sicura dei sotto-oggetti hw e analysis
var hw = data.hw || {};
var analysis = data.analysis || {};

// 4. Determinazione del Device Name
var devName = data.device_id || "sensore_001";
if (metadata.topic) {
    var parts = metadata.topic.split('/');
    if (parts.length > 1) {
        devName = parts[1];
    }
}

// 5. Ritorno della telemetria flattata
return {
   deviceName: devName,
   deviceType: 'Optical Biosensor',
   telemetry: {
       spore_count: analysis.spore_count !== undefined ? Number(analysis.spore_count) : 0,
       detected: analysis.detected ? 1 : 0,
       frame_id: data.frame_id || 0,
       sample_id: data.sample_id || "",
       cpu_temp_c: hw.cpu_temp_c || null,
       processing_time_s: hw.processing_time_s || null,
       ram_used_percent: hw.ram ? hw.ram.used_percent : null,
       disk_used_percent: hw.disk ? hw.disk.used_percent : null
   }
};
